def longest_substring_length(s)
  longest_length = 0
  substring_start_index = 0

  s.chars.each_with_index do |char, index|
    repeated_index = s[substring_start_index..index].rindex(char) || index + 1

    if repeated_index > substring_start_index
      substring_start_index = repeated_index
    end

    longest_length = [longest_length, index - substring_start_index + 1].max
  end

  longest_length
end
```
