function answer(data) {
  var groups = data.split(' ').map(function(s) {
    return s.split('').sort().join('');
  });

  var group1 = groups[0];
  var group2 = groups[1];

  var shorter_length = Math.min(group1.length, group2.length);

  var common_chars = '';
  for (var i = 0; i < shorter_length; i++) {
    if (group1[i] !== group2[i]) {
      break;
    }
    common_chars += group1[i];
  }

  return common_chars;
}
